(()=>{'use strict';const G=window.FeedbackDiagnostics,$=id=>document.getElementById(id);if(!G)return;
function install(kind){const prefix=kind==='blast'?'blast':'wind',host=$(prefix+'-time')?.closest('.lab');if(!host)return;
 const panel=document.createElement('details');panel.className='feedback-diagnostics';panel.id=kind+'-diagnostics';panel.innerHTML=`<summary>检查这组参数是否仍符合近似</summary><p>以下参数仅用于检查适用条件，不会悄悄修改上方自相似解。环境按完全电离纯氢、理想单原子气体估计声速。</p><div class="instrument-controls"><label for="${kind}-environment-temperature">环境温度 log₁₀ Tenv（K）<output id="${kind}-environment-temperature-value"></output><input type="range" id="${kind}-environment-temperature" min="3" max="6" step=".1" value="4"></label>${kind==='blast'?'<label for="blast-ejecta">抛射质量 Mej（M☉）<output id="blast-ejecta-value"></output><input type="range" id="blast-ejecta" min="1" max="20" step=".5" value="5"></label>':''}</div><div class="readout-row"><div><span>环境声速（km/s）</span><strong data-diagnostic="sound"></strong></div><div><span>马赫数 ℳ</span><strong data-diagnostic="mach"></strong></div>${kind==='blast'?'<div><span>扫掠质量 / 抛射质量</span><strong data-diagnostic="mass"></strong></div><div><span>辐射参考时间（kyr）</span><strong data-diagnostic="radiation"></strong></div>':''}</div><p class="lab-validity" data-diagnostic="status"></p><p class="lab-tool-note">声速 cₛ² = γ kBTenv/(μmp)，γ = 5/3，μ = 0.5。马赫数是模型速度与环境声速之比；3 和质量比 10 是教学诊断门槛，并非严格相界。温度较低时完全电离也可能需要外部光致电离维持。${kind==='blast'?'辐射参考时间依原书式(8.189)：trad ≈ 4.3×10⁴ (nH/cm⁻³)⁻⁵ᐟ⁹ E₅₁²ᐟ⁹ yr，定义为估计已损失初始能量的1/4；采用 nHe = nH/12 与原书的冷却近似，和上方纯氢密度模型的成分不同，只提供比较标尺，不是本页纯氢解的精确失效时间。':'恒星风模型包含外层薄壳的辐射损失，但仍假设内部气体绝热、持续注能且外部压力可忽略；弱激波时需要额外压力边界。'}</p>`;
 host.append(panel);const fmt=x=>x.toLocaleString('zh-CN',{maximumFractionDigits:3});let signature;
 function update(){const temp=10**+$(kind+'-environment-temperature').value,ejecta=kind==='blast'?+$('blast-ejecta').value:5,args={kind,temperature:temp,ejectaMass:ejecta,time:+$(kind+'-time').value,nH:10**+$(kind+'-n').value};if(kind==='blast')args.energy=10**+$('blast-E').value;else args.luminosity=10**+$('wind-L').value;const next=JSON.stringify(args);if(next===signature)return;signature=next;const r=G.evaluate(args);panel.dataset.mach=r.mach;panel.dataset.sweptToEjecta=r.sweptToEjecta;$(kind+'-environment-temperature-value').textContent=fmt(Math.log10(temp));if(kind==='blast')$('blast-ejecta-value').textContent=fmt(ejecta);panel.querySelector('[data-diagnostic=sound]').textContent=fmt(r.soundSpeed/1e5);panel.querySelector('[data-diagnostic=mach]').textContent=fmt(r.mach);if(kind==='blast'){panel.querySelector('[data-diagnostic=mass]').textContent=fmt(r.sweptToEjecta);panel.querySelector('[data-diagnostic=radiation]').textContent=fmt(r.radiativeReferenceYr/1000);}const status=panel.querySelector('[data-diagnostic=status]');status.dataset.level=r.warnings.length?'caution':'reference';panel.querySelector('summary').textContent='适用条件 · 马赫数 '+fmt(r.mach)+(r.warnings.length?' · '+r.warnings.length+' 项边界提示':' · 未触发当前诊断门槛');status.textContent=r.warnings.join(' ')||'这些检查暂未触发边界提示；这并不验证均匀介质、球对称、冷却、磁场或持续注能等其他假设。';}
 host.querySelectorAll('input').forEach(el=>el.addEventListener('input',update));const observer=new MutationObserver(update);for(const id of kind==='blast'?['blast-R','blast-v','blast-mass']:['wind-R','wind-v','wind-energy'])observer.observe($(id),{childList:true,subtree:true,characterData:true});update();
}
install('blast');install('wind');})();
